question:
Why does this code deadlock?

func (c *Counter) Inc() {
	c.mu.Lock()
	c.n++
	c.report() // report also calls c.mu.Lock()
}
func (c *Counter) report() {
	c.mu.Lock()
	defer c.mu.Unlock()
	log.Println(c.n)
}

Why does go vet warn 'passes lock by value' for this type, and why is it broken?

type Counter struct {
	mu sync.Mutex
	n  int
}
func (c Counter) Inc() {
	c.mu.Lock()
	c.n++
	c.mu.Unlock()
}
